-- Unified, private catalog of BIST and US listed equities. Snapshot sourced 2026-11-25.
-- Sources: KAP pazar listesi (https://kap.org.tr/tr/api/company/markets/pdf/pazarlar)
-- and Nasdaq Trader symbol directories (https://www.nasdaqtrader.com/Trader.aspx?id=symbollookup).
create table app_data.stock_universe (
    market text not null check (market in ('BIST', 'US')),
    symbol text not null,
    company_name text not null,
    exchange text not null,
    source text not null,
    sort_order integer not null default 1000,
    updated_at timestamptz not null default now(),
    primary key (market, symbol)
);

create index stock_universe_market_order_idx
    on app_data.stock_universe (market, sort_order, symbol);

alter table app_data.stock_universe enable row level security;
revoke all on table app_data.stock_universe from anon, authenticated, service_role;

